            mechanicsEn: "Base_CONNECTION + [M2_Cost_and_Misunderstanding_of_Communication = Judged_as_Inefficient_Trash_Destined_to_Fail; Perfect_Understander = Super_AI_Able_to_Auto-Fix_All_My_Logic_Bugs_and_Parse_Me_with_Infinite_Computing_Power; M5_Understanding = Forcibly_Prying_Open_Own_Skull_Demanding_Partner_Not_Only_Not_Feel_Disgust_but_Accurately_Read_Secrets_in_Every_Fold]",
